code_example:
int x = 42;
const int cx = x;
const int& crx = x;

// Plain auto: drops references and top-level const
auto a = x;      // int (copy)
auto b = cx;     // int (const dropped)
auto c = crx;    // int (reference and const dropped)

// Preserve const
const auto d = x;     // const int

// Preserve reference (avoid copy)
auto& e = x;          // int&
const auto& f = x;    // const int& (most common for avoiding copies)

// Explicit pointer
int* p = &x;
auto* ptr1 = &x;      // int* (explicit pointer)
auto ptr2 = &x;       // int* (also works)
// auto* err = x;     // ERROR: x is not pointer

// Universal reference (auto&&)
auto&& ur1 = x;       // int& (lvalue)
auto&& ur2 = 42;      // int&& (rvalue)
auto&& ur3 = std::move(x);  // int&& (rvalue)

// Range-based for with auto&&
for (auto&& elem : container) {
    // Accepts any element type without copy
}
